class OperatorError(RuntimeError):
    pass


class QuackExtensionCustodyBlocker(OperatorError):
    """Typed pre-authoritative-mutation extension-custody terminal."""

    _RESOURCE_REASONS = {
        errno.ENOSPC: "inotify_watch_quota_exhausted",
        errno.EMFILE: "inotify_instance_or_process_fd_quota_exhausted",
        errno.ENFILE: "system_file_descriptor_table_exhausted",
        errno.ENOMEM: "kernel_memory_unavailable",
    }

    def __init__(self, *, operation: str, errno_number: int) -> None:
        self.operation = operation
        self.errno_number = int(errno_number)
        self.errno_name = errno.errorcode.get(self.errno_number, "UNKNOWN")
        self.reason_code = self._RESOURCE_REASONS.get(
            self.errno_number,
            "extension_custody_unavailable",
        )
        self.retryable = self.errno_number in self._RESOURCE_REASONS
        super().__init__(
            f"{self.reason_code} during {self.operation} "
            f"({self.errno_name})"
        )

    def as_dict(self) -> dict[str, Any]:
        """Return a credential-free external-capability blocker receipt."""

        return {
            "schema": "sawm/quack-startup-capability-blocker@1",
            "valid": False,
            "terminal": "typed_external_capability",
            "phase": "pre_authoritative_mutation_extension_custody",
            "reason_code": self.reason_code,
            "operation": self.operation,
            "errno_number": self.errno_number,
            "errno_name": self.errno_name,
            "retryable": self.retryable,
            "retry_requires_changed_resource_evidence": self.retryable,
            "authoritative_database_opened": False,
            "owner_marker_created": False,
            "store_generation_changes": 0,
            "credential_changes": 0,
            "token_handoff_created": False,
            "task_status_changes": 0,
            "completion_changes": 0,
            "recovery": {
                "automatic_process_termination": False,
                "automatic_kernel_limit_change": False,
                "guidance": [
                    "release or fence stale watcher consumers through their own authority",
                    "or have an operator explicitly increase the inotify resource limit",
                    "retry only after the available-capacity evidence changes",
                ],
            },
        }


def _load_script(relative: str, name: str):
    path = REPO_ROOT / relative
    spec = importlib.util.spec_from_file_location(name, path)
    if spec is None or spec.loader is None:
        raise OperatorError(f"cannot load sealed operator script: {relative}")
    module = importlib.util.module_from_spec(spec)
    sys.modules[name] = module
    spec.loader.exec_module(module)
    return module


def _configured_board_scheduler_runtime() -> Any:
    """Import the source-checkout scheduler without ambient path authority.

    Plain execution of this nested operator script does not place the
    repository root on ``sys.path``.  Add that exact root only for the deferred
    operational import, then restore the caller's path byte-for-byte.  Module
    import and ``--help`` therefore remain side-effect free.
    """

    prior_path = list(sys.path)
    try:
        root = str(REPO_ROOT)
        if root not in sys.path:
            sys.path.insert(0, root)
        from ipfs_accelerate_py.agent_supervisor.runtime import (
            configured_board_scheduler,
        )
    finally:
        sys.path[:] = prior_path
    return configured_board_scheduler


def _config(path: Path) -> dict[str, Any]:
    value = json.loads(path.read_text(encoding="utf-8"))
    if not isinstance(value, dict):
        raise OperatorError("scheduler config must be an object")
    return value


def _emit(value: Mapping[str, Any]) -> int:
    secrets = {
        str(secret)
        for name, secret in os.environ.items()
        if name.endswith("_QUACK_TOKEN") and len(str(secret)) >= 8
    }

    def normalize(item: Any) -> Any:
        if isinstance(item, Mapping):
            normalized: dict[str, Any] = {}
            for key, child in item.items():
                if not isinstance(key, str):
                    raise OperatorError("operator JSON output keys must be strings")
                safe_key = key
                for secret in sorted(secrets, key=len, reverse=True):
                    safe_key = safe_key.replace(secret, "<redacted-quack-token>")
                if safe_key in normalized:
                    raise OperatorError("operator JSON output keys collide after redaction")
                normalized[safe_key] = normalize(child)
            return normalized
        if isinstance(item, (list, tuple)):
            return [normalize(child) for child in item]
        if item is None or isinstance(item, (bool, int)):
            return item
        if isinstance(item, float):
            if not math.isfinite(item):
                raise OperatorError("operator JSON output contains a nonfinite number")
            return item
        if isinstance(item, str):
            rendered = item
            for secret in sorted(secrets, key=len, reverse=True):
                rendered = rendered.replace(secret, "<redacted-quack-token>")
            return rendered
        raise OperatorError(
            f"operator JSON output contains unsupported {type(item).__name__}"
        )

    normalized = normalize(value)
    print(json.dumps(normalized, indent=2, sort_keys=True, allow_nan=False))
    return 0 if normalized.get("valid", True) is True else 2


_LIVE_QUACK_ENV_NAMES = (
    "IPFS_ACCELERATE_AGENT_QUACK_ENDPOINT",
    "IPFS_ACCELERATE_AGENT_STATE_STORE_ID",
    "IPFS_ACCELERATE_AGENT_QUACK_TOKEN",
    "IPFS_ACCELERATE_AGENT_STATE_STORE_GENERATION",
    "IPFS_ACCELERATE_AGENT_QUACK_MUTATION_BINDING",
    "IPFS_ACCELERATE_AGENT_QUACK_MUTATION_DIR",
    "SAWM_QUACK_TOKEN",
)


def _snapshot_live_quack_environment() -> dict[str, tuple[bool, str]]:
    """Capture the exact ambient bindings which live preflight may replace."""

    return {
        name: (name in os.environ, str(os.environ.get(name, "")))
        for name in _LIVE_QUACK_ENV_NAMES
    }


def _restore_live_quack_environment(
    snapshot: Mapping[str, tuple[bool, str]],
) -> None:
    """Restore an exact caller-owned environment after delegated scheduling."""

    if set(snapshot) != set(_LIVE_QUACK_ENV_NAMES):
        raise OperatorError("live Quack environment snapshot is incomplete")
    for name in _LIVE_QUACK_ENV_NAMES:
        present, value = snapshot[name]
        if present:
            os.environ[name] = value
        else:
            os.environ.pop(name, None)


def _live_quack_environment_secrets() -> set[str]:
    """Capture active credential values before restoring their ambient scope."""

    return {
        str(os.environ[name])
        for name in _LIVE_QUACK_ENV_NAMES
        if name.endswith("_QUACK_TOKEN")
        and name in os.environ
        and len(str(os.environ[name])) >= 8
    }


def _credential_safe_error(
    exc: BaseException,
    *,
    extra_secrets: Sequence[str] = (),
) -> str:
    """Render an operator error without exposing a live Quack credential."""

    message = f"{type(exc).__name__}: {exc}"
    notes = tuple(
        str(note)
        for note in (getattr(exc, "__notes__", ()) or ())
        if str(note)
    )
    if notes:
        message += " [" + "; ".join(notes) + "]"
    secrets = {
        str(value)
        for name, value in os.environ.items()
        if name.endswith("_QUACK_TOKEN") and len(str(value)) >= 8
    }
    secrets.update(
        str(value) for value in extra_secrets if len(str(value)) >= 8
    )
    for secret in sorted(secrets, key=len, reverse=True):
        message = message.replace(secret, "<redacted-quack-token>")
    return message


def _validator(relative: str, function: str) -> dict[str, Any]:
    module = _load_script(relative, "_sawm_operator_" + function)
    return dict(getattr(module, function)(REPO_ROOT))


def _materializer():
    return _load_script("scripts/materialize_semantic_addressed_world_model_program.py", "_sawm_operator_materializer")


