def _quack_args(config: Mapping[str, Any], command: str) -> list[str]:
    owner = config["quack_owner"]
    return [
        "--database", str(REPO_ROOT / owner["database_path"]),
        "--state-dir", str(REPO_ROOT / owner["state_dir"]),
        "--host", str(owner["host"]), "--port", str(owner["port"]),
        "--store-id", str(owner["store_id"]),
        "--repository-id", str(owner["repository_id"]),
        "--secret-handle", str(owner["secret_handle"]), "--json", command,
    ]


def _m70_published_owner_is_process_dead(config: Mapping[str, Any]) -> bool:
    """True when the published generation-48 owner PID is gone and listen is down."""

    owner = config.get("quack_owner")
    if not isinstance(owner, Mapping):
        return False
    status_path = (
        REPO_ROOT / str(owner.get("state_dir") or "") / "quack-state-server.status.json"
    )
    try:
        status = json.loads(status_path.read_text(encoding="utf-8"))
    except (OSError, TypeError, ValueError, json.JSONDecodeError):
        return False
    identity = status.get("identity") if isinstance(status, Mapping) else None
    if not isinstance(identity, Mapping):
        return False
    birth = identity.get("process_birth")
    try:
        pid = int(birth.get("pid") or 0) if isinstance(birth, Mapping) else 0
        generation = int(identity.get("generation") or 0)
    except (TypeError, ValueError):
        return False
    lifecycle = str(status.get("lifecycle") or "")
    if (
        generation != _M70_GENERATION
        or pid <= 1
        or lifecycle not in {"ready", "stopped", "starting"}
    ):
        return False
    if Path(f"/proc/{pid}").exists():
        return False
    probe = socket.socket()
    probe.settimeout(0.4)
    try:
        probe.connect(("127.0.0.1", int(_M70_TARGET_QUACK_PORT)))
        listening = True
    except OSError:
        listening = False
    finally:
        probe.close()
    return not listening


def _admit_isolated_lane_supervisor_recycle(
    *,
    owner_ready: bool,
    owner_alive: bool,
    master_alive: bool,
    dead_lane_count: int,
    master_capsule_fds_live: bool = False,
) -> dict[str, object]:
    """Isolated dead lanes require in-wave capsule relaunch, never coordinator kill.

    A live ready owner plus a live master already owns fenced lane birth.
    Killing that coordinator would interrupt healthy peer lanes.  When the
    master still holds its sealed capsule FDs, one isolated lane may be
    respawned from a live peer argv without replacing the coordinator.
    """

    if not owner_ready or not owner_alive:
        return {
            "admitted": False,
            "kill_coordinator": False,
            "reason": "owner_not_ready",
        }
    if dead_lane_count < 1:
        return {
            "admitted": False,
            "kill_coordinator": False,
            "reason": "no_dead_lanes",
        }
    if master_alive and master_capsule_fds_live:
        return {
            "admitted": True,
            "kill_coordinator": False,
            "in_wave_relaunch_required": True,
            "action": "lane_only_sealed_relaunch",
            "reason": "lane_only_sealed_relaunch",
        }
    if master_alive:
        return {
            "admitted": False,
            "kill_coordinator": False,
            "in_wave_relaunch_required": True,
            "reason": "healthy_coordinator_owns_in_wave_relaunch",
        }
    return {
        "admitted": True,
        "kill_coordinator": False,
        "reason": "master_down_isolated_lane_recycle",
    }


def _rewrite_isolated_lane_peer_argv(
    args: Sequence[str],
    *,
    peer_index: int,
    dead_index: int,
) -> list[str]:
    """Copy a live peer supervisor argv onto one isolated dead lane."""

    peer = int(peer_index)
    dead = int(dead_index)
    if peer < 0 or dead < 0 or peer == dead:
        raise ValueError("isolated lane relaunch indexes are invalid")
    rewritten = list(args)
    replacements = {
        f"/state/lane-{peer}": f"/state/lane-{dead}",
        f"sawm_lane_{peer}": f"sawm_lane_{dead}",
    }
    for index, value in enumerate(rewritten):
        for old, new in replacements.items():
            if old in value:
                rewritten[index] = value.replace(old, new)
    for index, value in enumerate(rewritten[:-1]):
        if value == "--task-shard-index" and rewritten[index + 1] == str(peer):
            rewritten[index + 1] = str(dead)
    return rewritten


def _isolated_lane_relaunch_pass_fds(native_src: int, capsule_src: int) -> tuple[int, ...]:
    """Pass only opened master memfds; destination 7/8 are created by dup2."""

    return tuple(dict.fromkeys((int(native_src), int(capsule_src))))


def _rewind_isolated_lane_relaunch_fds(descriptors: Sequence[int]) -> None:
    """Seek inherited capsule memfds back to offset 0 before spawn."""

    for descriptor in descriptors:
        try:
            os.lseek(int(descriptor), 0, os.SEEK_SET)
        except (OSError, TypeError, ValueError):
            continue


def _sealed_capsule_source_head(args: Sequence[str]) -> str:
    """Read the sealed control-plane pin from a live peer argv."""

    for index, value in enumerate(args[:-1]):
        if value != "--accepted-control-plane-pin-json":
            continue
        pin = json.loads(args[index + 1])
        if not isinstance(pin, Mapping):
            raise ValueError("sealed capsule pin is not a mapping")
        head = str(pin.get("source_head") or "")
        if re.fullmatch(r"[0-9a-f]{40}", head) is None:
            raise ValueError("sealed capsule source_head is invalid")
        return head
    raise ValueError("sealed capsule pin is missing")


def _isolated_exact_source_worktree_path(run_dir: Path, source_head: str) -> Path:
    return (Path(run_dir) / "worktrees" / f"exact-source-{source_head}").resolve()


def _isolated_exact_source_git(
    *arguments: str,
    cwd: Path,
    timeout: float,
) -> subprocess.CompletedProcess[str]:
    return subprocess.run(
        [
            "/usr/bin/git",
            "-c",
            "core.hooksPath=/dev/null",
            "-c",
            "core.fsmonitor=false",
            *arguments,
        ],
        cwd=str(cwd),
        env={
            "PATH": "/usr/bin:/bin",
            "GIT_CONFIG_NOSYSTEM": "1",
            "GIT_CONFIG_GLOBAL": "/dev/null",
            "GIT_NO_REPLACE_OBJECTS": "1",
            "GIT_OPTIONAL_LOCKS": "0",
            "GIT_TERMINAL_PROMPT": "0",
        },
        capture_output=True,
        text=True,
        check=False,
        timeout=timeout,
    )


def _ensure_isolated_exact_source_worktree(
    *,
    repo_root: Path,
    run_dir: Path,
    source_head: str,
) -> Path:
    """Create or reuse a clean worktree pinned to the sealed capsule source."""

    if re.fullmatch(r"[0-9a-f]{40}", source_head) is None:
        raise ValueError("isolated exact-source head is invalid")
    dest = _isolated_exact_source_worktree_path(run_dir, source_head)
    if dest.exists():
        observed = _isolated_exact_source_git(
            "rev-parse",
            "HEAD",
            cwd=dest,
            timeout=10.0,
        )
        dirty = _isolated_exact_source_git(
            "status",
            "--porcelain=v1",
            "--untracked-files=all",
            cwd=dest,
            timeout=30.0,
        )
        if (
            observed.returncode == 0
            and observed.stdout.strip() == source_head
            and dirty.returncode == 0
            and not dirty.stdout.strip()
        ):
            return dest
        raise ValueError("isolated exact-source worktree drifted")
    dest.parent.mkdir(parents=True, exist_ok=True)
    added = _isolated_exact_source_git(
        "worktree",
        "add",
        "--detach",
        str(dest),
        source_head,
        cwd=repo_root,
        timeout=180.0,
    )
    if added.returncode != 0:
        _isolated_exact_source_git("worktree", "prune", cwd=repo_root, timeout=30.0)
        added = _isolated_exact_source_git(
            "worktree",
            "add",
            "--detach",
            str(dest),
            source_head,
            cwd=repo_root,
            timeout=180.0,
        )
    if added.returncode != 0:
        raise ValueError(
            "isolated exact-source worktree add failed: "
            + (added.stderr or added.stdout or "")[-400:]
        )
    _isolated_exact_source_git(
        "submodule",
        "update",
        "--init",
        "--checkout",
        "--",
        "ipfs_datasets_py",
        "ipfs_kit_py",
        cwd=dest,
        timeout=180.0,
    )
    dirty = _isolated_exact_source_git(
        "status",
        "--porcelain=v1",
        "--untracked-files=all",
        cwd=dest,
        timeout=30.0,
    )
    if dirty.returncode != 0 or dirty.stdout.strip():
        raise ValueError("isolated exact-source worktree is not clean")
    return dest


def _rewrite_isolated_lane_relative_run_paths(
    value: str,
    *,
    repo_root: Path,
    run_dir: Path,
) -> str:
    """Make run-dir relative paths absolute so cwd can be the pin worktree."""

    if (
        not value
        or value.startswith("/")
        or value.startswith("{")
        or value.startswith("[")
    ):
        return value
    try:
        relative = Path(run_dir).resolve().relative_to(Path(repo_root).resolve()).as_posix()
    except ValueError:
        return value
    if not relative or relative == ".":
        return value
    if value == relative or value.startswith(relative + "/"):
        return str(Path(run_dir).resolve()) + value[len(relative) :]
    return value


def _rewrite_isolated_lane_operational_env_paths(
    env: Mapping[str, str],
    *,
    repo_root: Path,
    run_dir: Path,
) -> dict[str, str]:
    """Absolutize operational run-dir paths without rewriting hashed JSON."""

    rewritten = dict(env)
    try:
        relative = Path(run_dir).resolve().relative_to(Path(repo_root).resolve()).as_posix()
    except ValueError:
        return rewritten
    if not relative or relative == ".":
        return rewritten
    absolute = str(Path(run_dir).resolve())
    operational = {
        "IPFS_ACCELERATE_AGENT_DATABASE_PROGRAM_JSON",
        "IPFS_ACCELERATE_AGENT_STATE_STORE_ID",
        "IPFS_ACCELERATE_AGENT_EVENT_STORE_PATH",
        "IPFS_ACCELERATE_AGENT_RUNTIME_REGISTRY_PATH",
    }
    for key in operational:
        value = rewritten.get(key)
        if not isinstance(value, str) or not value:
            continue
        if value.startswith("{"):
            rewritten[key] = value.replace('"' + relative, '"' + absolute)
        else:
            rewritten[key] = _rewrite_isolated_lane_relative_run_paths(
                value, repo_root=repo_root, run_dir=run_dir
            )
    return rewritten


def _overlay_live_run_dir_into_exact_source(
    *,
    pin_root: Path,
    repo_root: Path,
    run_dir: Path,
) -> Path:
    """Expose live run-dir files under the pin cwd via an ignored overlay."""

    pin_root = Path(pin_root).resolve()
    repo_root = Path(repo_root).resolve()
    run_dir = Path(run_dir).resolve()
    relative = run_dir.relative_to(repo_root)
    dest = pin_root / relative
    dest.parent.mkdir(parents=True, exist_ok=True)
    if dest.exists() or dest.is_symlink():
        if dest.resolve() != run_dir:
            raise ValueError("isolated exact-source run-dir overlay drifted")
    else:
        os.symlink(str(run_dir), dest, target_is_directory=True)
    git_dir = _isolated_exact_source_git(
        "rev-parse",
        "--absolute-git-dir",
        cwd=pin_root,
        timeout=10.0,
    )
    if git_dir.returncode != 0:
        raise ValueError("isolated exact-source git dir is unavailable")
    exclude = Path(git_dir.stdout.strip()) / "info" / "exclude"
    exclude.parent.mkdir(parents=True, exist_ok=True)
    overlay_root = relative.parts[:3]
    overlay_prefix = "/".join(overlay_root) if overlay_root else relative.as_posix()
    patterns = (
        "/" + overlay_prefix,
        "/" + overlay_prefix + "/",
        "/" + relative.as_posix(),
        "/" + relative.as_posix() + "/",
    )
    existing = exclude.read_text(encoding="utf-8") if exclude.exists() else ""
    lines = existing.splitlines()
    missing = [pattern for pattern in patterns if pattern not in lines]
    if missing:
        with exclude.open("a", encoding="utf-8") as handle:
            if existing and not existing.endswith("\n"):
                handle.write("\n")
            handle.write("\n".join(missing) + "\n")
    dirty = _isolated_exact_source_git(
        "status",
        "--porcelain=v1",
        "--untracked-files=all",
        cwd=pin_root,
        timeout=30.0,
    )
    if dirty.returncode != 0 or dirty.stdout.strip():
        raise ValueError("isolated exact-source overlay dirtied the pin checkout")
    return dest


def _rewrite_isolated_lane_peer_env(
    env: Mapping[str, str],
    *,
    peer_index: int,
    dead_index: int,
) -> dict[str, str]:
    """Copy a live peer supervisor environment onto one isolated dead lane."""

    peer = int(peer_index)
    dead = int(dead_index)
    rewritten = dict(env)
    replacements = {
        f"/state/lane-{peer}": f"/state/lane-{dead}",
        f"sawm_lane_{peer}": f"sawm_lane_{dead}",
        f"semantic-addressed-world-model-v1-{peer}": (
            f"semantic-addressed-world-model-v1-{dead}"
        ),
    }
    for key, value in list(rewritten.items()):
        for old, new in replacements.items():
            if old in value:
                rewritten[key] = value.replace(old, new)
    return rewritten


def _pid_alive(pid: int) -> bool:
    if pid <= 1:
        return False
    try:
        os.kill(pid, 0)
    except ProcessLookupError:
        return False
    except PermissionError:
        return True
    except OSError:
        return False
    return True


def _recycle_isolated_lane_from_live_peer(
    *,
    repo_root: Path,
    run_dir: Path,
    master_pid: int,
    peer_supervisor_pid: int,
    dead_lane_index: int,
    peer_lane_index: int,
    native_fd: int = 7,
    capsule_fd: int = 8,
) -> dict[str, object]:
    """Respawn one isolated lane from a live peer's sealed argv and master FDs."""

    repo_root = Path(repo_root)
    run_dir = Path(run_dir)
    admission = _admit_isolated_lane_supervisor_recycle(
        owner_ready=True,
        owner_alive=True,
        master_alive=_pid_alive(int(master_pid)),
        dead_lane_count=1,
        master_capsule_fds_live=all(
            Path(f"/proc/{int(master_pid)}/fd/{int(fd)}").exists()
            for fd in (native_fd, capsule_fd)
        ),
    )
    if not admission.get("admitted") or admission.get("kill_coordinator"):
        return {
            "restarted": False,
            "reason": str(admission.get("reason") or "not_admitted"),
            "admission": admission,
        }
    if not _pid_alive(int(peer_supervisor_pid)):
        return {"restarted": False, "reason": "peer_supervisor_dead"}
    peer_args = [
        part.decode("utf-8", "strict")
        for part in Path(f"/proc/{int(peer_supervisor_pid)}/cmdline")
        .read_bytes()
        .split(b"\0")
        if part
    ]
    argv = _rewrite_isolated_lane_peer_argv(
        peer_args,
        peer_index=int(peer_lane_index),
        dead_index=int(dead_lane_index),
    )
    peer_env = {}
    for item in Path(f"/proc/{int(peer_supervisor_pid)}/environ").read_bytes().split(
        b"\0"
    ):
        if not item or b"=" not in item:
            continue
        key, value = item.split(b"=", 1)
        peer_env[key.decode("utf-8", "strict")] = value.decode("utf-8", "strict")
    env = _rewrite_isolated_lane_peer_env(
        peer_env,
        peer_index=int(peer_lane_index),
        dead_index=int(dead_lane_index),
    )
    try:
        source_head = _sealed_capsule_source_head(argv)
        cwd = _ensure_isolated_exact_source_worktree(
            repo_root=repo_root,
            run_dir=run_dir,
            source_head=source_head,
        )
        _overlay_live_run_dir_into_exact_source(
            pin_root=cwd,
            repo_root=repo_root,
            run_dir=run_dir,
        )
    except (
        OSError,
        TypeError,
        ValueError,
        json.JSONDecodeError,
        subprocess.TimeoutExpired,
        subprocess.SubprocessError,
    ) as exc:
        return {
            "restarted": False,
            "reason": f"exact_source_worktree:{type(exc).__name__}",
            "admission": admission,
        }
    log_dir = run_dir / "state" / f"lane-{int(dead_lane_index)}"
    log_dir.mkdir(parents=True, exist_ok=True)
    stamp = time.strftime("%Y%m%dT%H%M%SZ", time.gmtime())
    log_path = log_dir / (
        f"sawm_lane_{int(dead_lane_index)}_8h_run_{stamp}.log"
    )
    native_src = os.open(
        f"/proc/{int(master_pid)}/fd/{int(native_fd)}",
        os.O_RDONLY | getattr(os, "O_CLOEXEC", 0),
    )
    capsule_src = os.open(
        f"/proc/{int(master_pid)}/fd/{int(capsule_fd)}",
        os.O_RDONLY | getattr(os, "O_CLOEXEC", 0),
    )
    _rewind_isolated_lane_relaunch_fds((native_src, capsule_src))
    native_dst = int(native_fd)
    capsule_dst = int(capsule_fd)

    def _dup_cloexec(src: int) -> int:
        copied = os.dup(src)
        flags = fcntl.fcntl(copied, fcntl.F_GETFD)
        fcntl.fcntl(copied, fcntl.F_SETFD, flags | fcntl.FD_CLOEXEC)
        return copied

    saved_dst: dict[int, int] = {}
    for dst in (native_dst, capsule_dst):
        try:
            saved_dst[dst] = _dup_cloexec(dst)
        except OSError:
            pass

    def _restore_parent_dst() -> None:
        for dst, saved in saved_dst.items():
            try:
                os.dup2(saved, dst)
            except OSError:
                pass
            try:
                os.close(saved)
            except OSError:
                pass
        for src in (native_src, capsule_src):
            try:
                os.close(src)
            except OSError:
                pass

    try:
        os.dup2(native_src, native_dst)
        os.dup2(capsule_src, capsule_dst)
        _rewind_isolated_lane_relaunch_fds((native_dst, capsule_dst))
        for fd in (native_dst, capsule_dst):
            flags = fcntl.fcntl(fd, fcntl.F_GETFD)
            fcntl.fcntl(fd, fcntl.F_SETFD, flags & ~fcntl.FD_CLOEXEC)
            try:
                os.set_inheritable(fd, True)
            except OSError:
                pass
    except OSError as exc:
        _restore_parent_dst()
        return {
            "restarted": False,
            "reason": f"{type(exc).__name__}",
            "admission": admission,
        }

    handle = log_path.open("ab")
    try:
        process = subprocess.Popen(
            argv,
            cwd=str(cwd),
            env=env,
            stdin=subprocess.DEVNULL,
            stdout=handle,
            stderr=subprocess.STDOUT,
            close_fds=True,
            pass_fds=_isolated_lane_relaunch_pass_fds(native_dst, capsule_dst),
            start_new_session=True,
        )
    except Exception as exc:
        handle.close()
        _restore_parent_dst()
        return {
            "restarted": False,
            "reason": f"{type(exc).__name__}",
            "admission": admission,
        }
    handle.close()
    _restore_parent_dst()
    deadline = time.monotonic() + 8.0
    while time.monotonic() < deadline:
        code = process.poll()
        if code is not None:
            return {
                "restarted": False,
                "reason": f"child_exited:{code}",
                "new_pid": int(process.pid),
                "log_path": str(log_path),
                "cwd": str(cwd),
                "source_head": source_head,
                "admission": admission,
            }
        time.sleep(0.2)
    code = process.poll()
    if code is not None:
        return {
            "restarted": False,
            "reason": f"child_exited:{code}",
            "new_pid": int(process.pid),
            "log_path": str(log_path),
            "cwd": str(cwd),
            "source_head": source_head,
            "admission": admission,
        }
    return {
        "restarted": True,
        "new_pid": int(process.pid),
        "log_path": str(log_path),
        "cwd": str(cwd),
        "source_head": source_head,
        "admission": admission,
    }


def _m70_published_owner_is_stale_ready(config: Mapping[str, Any]) -> bool:
    """True when generation-48 is published ready but the process and listen are gone."""

    if not _m70_published_owner_is_process_dead(config):
        return False
    owner = config.get("quack_owner")
    if not isinstance(owner, Mapping):
        return False
    status_path = (
        REPO_ROOT / str(owner.get("state_dir") or "") / "quack-state-server.status.json"
    )
    try:
        status = json.loads(status_path.read_text(encoding="utf-8"))
    except (OSError, TypeError, ValueError, json.JSONDecodeError):
        return False
    identity = status.get("identity") if isinstance(status, Mapping) else None
    if not isinstance(identity, Mapping):
        return False
    return (
        str(status.get("lifecycle") or "") == "ready"
        and str(identity.get("status") or "") == "ready"
    )


def _m69_published_owner_is_process_dead(config: Mapping[str, Any]) -> bool:
    """True when the published generation-47 owner PID is gone and listen is down."""

    owner = config.get("quack_owner")
    if not isinstance(owner, Mapping):
        return False
    status_path = (
        REPO_ROOT / str(owner.get("state_dir") or "") / "quack-state-server.status.json"
    )
    try:
        status = json.loads(status_path.read_text(encoding="utf-8"))
    except (OSError, TypeError, ValueError, json.JSONDecodeError):
        return False
    identity = status.get("identity") if isinstance(status, Mapping) else None
    if not isinstance(identity, Mapping):
        return False
    birth = identity.get("process_birth")
    try:
        pid = int(birth.get("pid") or 0) if isinstance(birth, Mapping) else 0
        generation = int(identity.get("generation") or 0)
    except (TypeError, ValueError):
        return False
    lifecycle = str(status.get("lifecycle") or "")
    if (
        generation != _M69_GENERATION
        or pid <= 1
        or lifecycle not in {"ready", "stopped", "starting"}
    ):
        return False
    if Path(f"/proc/{pid}").exists():
        return False
    probe = socket.socket()
    probe.settimeout(0.4)
    try:
        probe.connect(("127.0.0.1", int(_M69_TARGET_QUACK_PORT)))
        listening = True
    except OSError:
        listening = False
    finally:
        probe.close()
    return not listening


